 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seedrow = next(r for r, row in enumerate(grid) if sum(v != 0 for v in row) == 3)
    seeds = [(c, grid[seedrow][c]) for c in range(w) if grid[seedrow][c] != 0]
    seedcols = {c for c, _ in seeds}
    # Each color in the three-cell seed extends vertically.
    for c, color in seeds:
        for r in range(h):
            out[r][c] = color
    # The two outer colors extend horizontally to their matching markers.
    for c, color in (seeds[0], seeds[-1]):
        for r in range(h):
            for tc in range(w):
                if grid[r][tc] == color and not (r == seedrow and tc in seedcols):
                    for x in range(min(c, tc), max(c, tc) + 1):
                        out[r][x] = color
    return out
